<template><section class="flex h-full min-h-0 flex-col bg-neutral-100 p-4 sm:p-6"><header><p class="text-sm font-medium text-neutral-500">{{ route.meta.group }}</p><h1 class="mt-1 text-2xl font-semibold text-neutral-900">{{ route.meta.title }}</h1></header><div class="mt-4 flex min-h-0 flex-1 flex-col gap-4"><div class="flex shrink-0 gap-2 rounded-lg border border-neutral-200 bg-white px-3 py-2"><button class="rounded-md bg-violet-600 px-3 py-1.5 text-sm text-white" type="button" @click="input = 'TangTool Base64 示例'">示例</button><button class="rounded-md bg-blue-600 px-3 py-1.5 text-sm text-white" type="button" @click="encode">Base64 编码</button><button class="rounded-md bg-cyan-600 px-3 py-1.5 text-sm text-white" type="button" @click="decode">Base64 解码</button><button class="rounded-md bg-emerald-600 px-3 py-1.5 text-sm text-white disabled:opacity-50" type="button" :disabled="result === ''" @click="copy">复制</button><button class="rounded-md bg-red-600 px-3 py-1.5 text-sm text-white" type="button" @click="clear">清除</button><p v-if="status" class="ml-auto text-sm text-emerald-700">{{ status }}</p></div><div class="grid min-h-0 flex-1 gap-4 lg:grid-cols-2"><textarea v-model="input" class="min-h-0 resize-none rounded-lg border border-neutral-200 bg-white p-3 text-sm" aria-label="Base64 输入" placeholder="请输入文本" @input="reset"></textarea><div class="flex min-h-0 flex-col rounded-lg border border-neutral-200 bg-white"><textarea class="min-h-0 flex-1 resize-none bg-neutral-50 p-3 font-mono text-sm" aria-label="Base64 结果" :value="result" readonly placeholder="结果显示在这里"></textarea><p class="border-t border-neutral-100 px-3 py-2 text-xs text-neutral-500">Base64 是编码方式，不是加密。</p><p v-if="error" class="border-t border-red-100 bg-red-50 px-3 py-2 text-sm text-red-700">{{ error }}</p></div></div></div></section></template>
<script setup lang="ts">
import { writeText } from "@tauri-apps/plugin-clipboard-manager"; import { ref } from "vue"; import { useRoute } from "vue-router";
const route = useRoute(); const input = ref(""); const result = ref(""); const error = ref(""); const status = ref("");
function encode() { try { result.value = btoa(String.fromCharCode(...new TextEncoder().encode(input.value))); error.value = ""; status.value = "编码完成"; } catch { error.value = "Base64 编码失败"; } }
function decode() { try { const bytes = Uint8Array.from(atob(input.value), (char) => char.charCodeAt(0)); result.value = new TextDecoder().decode(bytes); error.value = ""; status.value = "解码完成"; } catch { result.value = ""; error.value = "Base64 内容无效，请检查字符和填充符号"; status.value = ""; } }
async function copy() { await writeText(result.value); status.value = "已复制到剪贴板"; } function reset() { result.value = ""; error.value = ""; status.value = ""; } function clear() { input.value = ""; reset(); }
</script>
